package com.payshield.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="idempotency_records") public class IdempotencyRecord { @Id private UUID id; @Column(unique=true,nullable=false) private String idempotencyKey; @Column(nullable=false) private String requestHash; @Column(nullable=false) private String resourceType; private UUID resourceId; @Column(nullable=false) private Instant createdAt; protected IdempotencyRecord(){} public IdempotencyRecord(String key,String hash,String type){id=UUID.randomUUID();idempotencyKey=key;requestHash=hash;resourceType=type;createdAt=Instant.now();} public String getRequestHash(){return requestHash;} public UUID getResourceId(){return resourceId;} public void setResourceId(UUID resourceId){this.resourceId=resourceId;} }
